"""Frozen controlled operational facts and named Build start."""
# ruff: noqa: E501

TABLES = ('operational_asset_sentinels', 'build_execution_assessments', 'build_operational_facts', 'build_authorization_decisions', 'build_current_execution_assessments', 'build_operational_current', 'build_current_authorizations', 'build_starts', 'operational_material_holds', 'operational_resource_occupancies')

SCHEMA_SQL = ("\nCREATE TABLE operational_asset_sentinels (\n\tkind VARCHAR(16) NOT NULL, \n\texternal_key VARCHAR(64) NOT NULL, \n\tidentity JSONB NOT NULL, \n\trevision INTEGER NOT NULL, \n\tdata_sha256 VARCHAR(64) NOT NULL, \n\tdata JSONB NOT NULL, \n\toccupancy_epoch INTEGER NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, id), \n\tUNIQUE (tenant_id, kind, external_key), \n\tCHECK (kind IN ('material','resource') AND revision>0 AND occupancy_epoch>0)\n)\n\n", 'CREATE INDEX ix_operational_asset_sentinels_tenant_id ON operational_asset_sentinels (tenant_id)', "\nCREATE TABLE build_execution_assessments (\n\tproduct_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tbuild_id UUID NOT NULL, \n\tbuild_revision INTEGER NOT NULL, \n\tengineering_configuration_id UUID NOT NULL, \n\tmanufacturing_configuration_id UUID NOT NULL, \n\tengineering_configuration_revision INTEGER NOT NULL, \n\tmanufacturing_configuration_revision INTEGER NOT NULL, \n\trevision INTEGER NOT NULL, \n\tprevious_assessment_id UUID, \n\tprevious_revision INTEGER, \n\towner_id UUID NOT NULL, \n\tvisibility VARCHAR(16) NOT NULL, \n\tstatus VARCHAR(32) NOT NULL, \n\texecution_scope JSONB NOT NULL, \n\tresult JSONB NOT NULL, \n\tsnapshot_sha256 VARCHAR(64) NOT NULL, \n\trequired_source_read_set JSONB NOT NULL, \n\tintent_digest VARCHAR(64) NOT NULL, \n\treason TEXT NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, id), \n\tUNIQUE (tenant_id, product_id, build_id, revision), \n\tUNIQUE (tenant_id, product_id, project_id, build_id, id, revision), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id, engineering_configuration_id, manufacturing_configuration_id) REFERENCES builds (tenant_id, product_id, project_id, id, engineering_configuration_id, manufacturing_configuration_id), \n\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id, previous_assessment_id, previous_revision) REFERENCES build_execution_assessments (tenant_id, product_id, project_id, build_id, id, revision), \n\tCHECK (revision > 0 AND build_revision > 0 AND engineering_configuration_revision > 0 AND manufacturing_configuration_revision > 0), \n\tCHECK (status IN ('UNKNOWN','BLOCKED','READY_WITH_CONDITIONS','READY') AND visibility IN ('private','product')), \n\tCHECK ((revision = 1 AND previous_assessment_id IS NULL AND previous_revision IS NULL) OR (previous_assessment_id IS NOT NULL AND previous_assessment_id <> id AND previous_revision IS NOT NULL AND revision = previous_revision + 1))\n)\n\n", 'CREATE INDEX ix_build_execution_assessments_tenant_id ON build_execution_assessments (tenant_id)', "\nCREATE TABLE build_operational_facts (\n\tproduct_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tbuild_id UUID NOT NULL, \n\tbuild_revision INTEGER NOT NULL, \n\towner_id UUID NOT NULL, \n\tvisibility VARCHAR(16) NOT NULL, \n\tissuer_key VARCHAR(100) NOT NULL, \n\tissuer_version VARCHAR(100) NOT NULL, \n\tissuer_epoch INTEGER NOT NULL, \n\tnature VARCHAR(16) NOT NULL, \n\texternal_id VARCHAR(200) NOT NULL, \n\tseries_id UUID NOT NULL, \n\trevision INTEGER NOT NULL, \n\tprevious_id UUID, \n\tprevious_revision INTEGER, \n\tstate VARCHAR(16) NOT NULL, \n\tvalid_from TIMESTAMP WITH TIME ZONE NOT NULL, \n\tvalid_until TIMESTAMP WITH TIME ZONE NOT NULL, \n\tbinding JSONB NOT NULL, \n\tdata JSONB NOT NULL, \n\tsources JSONB NOT NULL, \n\trequired_source_read_set JSONB NOT NULL, \n\tsource_basis JSONB NOT NULL, \n\tfact_sha256 VARCHAR(64) NOT NULL, \n\treason TEXT NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, project_id, build_id, id, revision), \n\tUNIQUE (tenant_id, product_id, build_id, series_id, revision), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id) REFERENCES builds (tenant_id, product_id, project_id, id), \n\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id, previous_id, previous_revision) REFERENCES build_operational_facts (tenant_id, product_id, project_id, build_id, id, revision), \n\tCHECK (revision>0 AND build_revision>0 AND issuer_epoch>0 AND valid_until>valid_from), \n\tCHECK (state IN ('active','withdrawn') AND nature IN ('real','synthetic') AND visibility IN ('private','product')), \n\tCHECK ((revision=1 AND previous_id IS NULL AND previous_revision IS NULL AND series_id=id) OR (previous_id IS NOT NULL AND previous_id<>id AND previous_revision>0 AND revision=previous_revision+1))\n)\n\n", 'CREATE INDEX ix_build_operational_facts_tenant_id ON build_operational_facts (tenant_id)', "\nCREATE TABLE build_authorization_decisions (\n\tproduct_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tbuild_id UUID NOT NULL, \n\tengineering_configuration_id UUID NOT NULL, \n\tmanufacturing_configuration_id UUID NOT NULL, \n\trole VARCHAR(24) NOT NULL, \n\trevision INTEGER NOT NULL, \n\tprevious_decision_id UUID, \n\tprevious_revision INTEGER, \n\tassessment_id UUID NOT NULL, \n\tassessment_revision INTEGER NOT NULL, \n\tassessment_sha256 VARCHAR(64) NOT NULL, \n\towner_id UUID NOT NULL, \n\tvisibility VARCHAR(16) NOT NULL, \n\taction VARCHAR(16) NOT NULL, \n\tstatus VARCHAR(16) NOT NULL, \n\tvalid_until TIMESTAMP WITH TIME ZONE NOT NULL, \n\tauthority_snapshot JSONB NOT NULL, \n\tfact_binding JSONB NOT NULL, \n\tsources JSONB NOT NULL, \n\trequired_source_read_set JSONB NOT NULL, \n\tsnapshot_sha256 VARCHAR(64) NOT NULL, \n\tintent_digest VARCHAR(64) NOT NULL, \n\treason TEXT NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, id), \n\tUNIQUE (tenant_id, product_id, build_id, role, revision), \n\tUNIQUE (tenant_id, product_id, project_id, build_id, role, id, revision), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id, engineering_configuration_id, manufacturing_configuration_id) REFERENCES builds (tenant_id, product_id, project_id, id, engineering_configuration_id, manufacturing_configuration_id), \n\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id, assessment_id, assessment_revision) REFERENCES build_execution_assessments (tenant_id, product_id, project_id, build_id, id, revision), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id, role, previous_decision_id, previous_revision) REFERENCES build_authorization_decisions (tenant_id, product_id, project_id, build_id, role, id, revision), \n\tCHECK (role IN ('engineering','manufacturing') AND revision > 0 AND assessment_revision > 0), \n\tCHECK (visibility IN ('private','product') AND ((action = 'approve' AND status = 'approved') OR (action = 'revoke' AND status = 'revoked'))), \n\tCHECK ((revision = 1 AND previous_decision_id IS NULL AND previous_revision IS NULL) OR (previous_decision_id IS NOT NULL AND previous_decision_id <> id AND previous_revision IS NOT NULL AND revision = previous_revision + 1))\n)\n\n", 'CREATE INDEX ix_build_authorization_decisions_tenant_id ON build_authorization_decisions (tenant_id)', '\nCREATE TABLE build_current_execution_assessments (\n\tproduct_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tbuild_id UUID NOT NULL, \n\tassessment_id UUID NOT NULL, \n\tassessment_revision INTEGER NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, build_id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id, assessment_id, assessment_revision) REFERENCES build_execution_assessments (tenant_id, product_id, project_id, build_id, id, revision), \n\tCHECK (assessment_revision > 0)\n)\n\n', 'CREATE INDEX ix_build_current_execution_assessments_tenant_id ON build_current_execution_assessments (tenant_id)', '\nCREATE TABLE build_operational_current (\n\tproduct_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tbuild_id UUID NOT NULL, \n\tfact_id UUID NOT NULL, \n\tfact_revision INTEGER NOT NULL, \n\tepoch INTEGER NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, build_id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id, fact_id, fact_revision) REFERENCES build_operational_facts (tenant_id, product_id, project_id, build_id, id, revision), \n\tCHECK (fact_revision>0 AND epoch>0)\n)\n\n', 'CREATE INDEX ix_build_operational_current_tenant_id ON build_operational_current (tenant_id)', "\nCREATE TABLE build_current_authorizations (\n\tproduct_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tbuild_id UUID NOT NULL, \n\trole VARCHAR(24) NOT NULL, \n\tdecision_id UUID NOT NULL, \n\tdecision_revision INTEGER NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, build_id, role), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id, role, decision_id, decision_revision) REFERENCES build_authorization_decisions (tenant_id, product_id, project_id, build_id, role, id, revision), \n\tCHECK (decision_revision > 0 AND role IN ('engineering','manufacturing'))\n)\n\n", 'CREATE INDEX ix_build_current_authorizations_tenant_id ON build_current_authorizations (tenant_id)', "\nCREATE TABLE build_starts (\n\tproduct_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tbuild_id UUID NOT NULL, \n\tbuild_revision INTEGER NOT NULL, \n\tengineering_configuration_id UUID NOT NULL, \n\tmanufacturing_configuration_id UUID NOT NULL, \n\tassessment_id UUID NOT NULL, \n\tassessment_revision INTEGER NOT NULL, \n\tassessment_sha256 VARCHAR(64) NOT NULL, \n\tengineering_authorization_id UUID NOT NULL, \n\tengineering_authorization_revision INTEGER NOT NULL, \n\tmanufacturing_authorization_id UUID NOT NULL, \n\tmanufacturing_authorization_revision INTEGER NOT NULL, \n\tengineering_role VARCHAR(24) NOT NULL, \n\tmanufacturing_role VARCHAR(24) NOT NULL, \n\trevision INTEGER NOT NULL, \n\towner_id UUID NOT NULL, \n\tvisibility VARCHAR(16) NOT NULL, \n\tstatus VARCHAR(24) NOT NULL, \n\toccurred_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\toccurred_timezone VARCHAR(160) NOT NULL, \n\texecution_scope JSONB NOT NULL, \n\tevent_source JSONB NOT NULL, \n\tauthority_snapshot JSONB NOT NULL, \n\treservations JSONB NOT NULL, \n\tsources JSONB NOT NULL, \n\trequired_source_read_set JSONB NOT NULL, \n\tsnapshot_sha256 VARCHAR(64) NOT NULL, \n\tintent_digest VARCHAR(64) NOT NULL, \n\treason TEXT NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, id), \n\tUNIQUE (tenant_id, product_id, project_id, build_id, id), \n\tUNIQUE (tenant_id, product_id, build_id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id, engineering_configuration_id, manufacturing_configuration_id) REFERENCES builds (tenant_id, product_id, project_id, id, engineering_configuration_id, manufacturing_configuration_id), \n\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id, assessment_id, assessment_revision) REFERENCES build_execution_assessments (tenant_id, product_id, project_id, build_id, id, revision), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id, engineering_role, engineering_authorization_id, engineering_authorization_revision) REFERENCES build_authorization_decisions (tenant_id, product_id, project_id, build_id, role, id, revision), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id, manufacturing_role, manufacturing_authorization_id, manufacturing_authorization_revision) REFERENCES build_authorization_decisions (tenant_id, product_id, project_id, build_id, role, id, revision), \n\tCHECK (revision = 1 AND status = 'executing' AND build_revision > 0 AND assessment_revision > 0), \n\tCHECK (visibility IN ('private','product') AND engineering_role = 'engineering' AND manufacturing_role = 'manufacturing')\n)\n\n", 'CREATE INDEX ix_build_starts_tenant_id ON build_starts (tenant_id)', '\nCREATE TABLE operational_material_holds (\n\tproduct_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tbuild_id UUID NOT NULL, \n\towner_execution_id UUID NOT NULL, \n\tasset_id UUID NOT NULL, \n\tbom_item_id VARCHAR(200) NOT NULL, \n\tquantity NUMERIC(24, 12) NOT NULL, \n\tunit VARCHAR(200) NOT NULL, \n\tintent_digest VARCHAR(64) NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, build_id, asset_id, bom_item_id), \n\tFOREIGN KEY(tenant_id, asset_id) REFERENCES operational_asset_sentinels (tenant_id, id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id) REFERENCES builds (tenant_id, product_id, project_id, id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id, owner_execution_id) REFERENCES build_starts (tenant_id, product_id, project_id, build_id, id) DEFERRABLE INITIALLY DEFERRED, \n\tCHECK (quantity>0)\n)\n\n', 'CREATE INDEX ix_operational_material_holds_tenant_id ON operational_material_holds (tenant_id)', '\nCREATE TABLE operational_resource_occupancies (\n\tproduct_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tbuild_id UUID NOT NULL, \n\towner_execution_id UUID NOT NULL, \n\tasset_id UUID NOT NULL, \n\tresource_id UUID NOT NULL, \n\tresource_revision INTEGER NOT NULL, \n\twindow_start TIMESTAMP WITH TIME ZONE NOT NULL, \n\twindow_finish TIMESTAMP WITH TIME ZONE NOT NULL, \n\tunits NUMERIC(24, 12) NOT NULL, \n\tintent_digest VARCHAR(64) NOT NULL, \n\treservation JSONB NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, build_id, asset_id), \n\tFOREIGN KEY(tenant_id, asset_id) REFERENCES operational_asset_sentinels (tenant_id, id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id) REFERENCES builds (tenant_id, product_id, project_id, id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id, owner_execution_id) REFERENCES build_starts (tenant_id, product_id, project_id, build_id, id) DEFERRABLE INITIALLY DEFERRED, \n\tCHECK (resource_revision>0 AND units>0 AND units<=1000 AND window_finish>window_start)\n)\n\n', 'CREATE INDEX ix_operational_resource_occupancies_tenant_id ON operational_resource_occupancies (tenant_id)')
